import sys, threading, time
sys.path.insert(0, sys.argv[1])
YIELD = len(sys.argv) < 3 or sys.argv[2] != "noyield"
from counter import Counter

class Store:
    def record_visit(self):
        if YIELD:
            time.sleep(0.001)  # I/O yields the GIL

def run(n_threads=20, per=20):
    c = Counter(Store())
    ts = [threading.Thread(target=lambda: [c.hit() for _ in range(per)]) for _ in range(n_threads)]
    [t.start() for t in ts]
    [t.join() for t in ts]
    return c.count, n_threads * per

for _ in range(3):
    print(run())

